const DEFAULTS = Object.freeze({ timeout: 5000, retries: 3, baseUrl: '' });

export function createClient(userOptions = {}) {
  const options = { ...DEFAULTS, ...userOptions };
  if (!options.baseUrl) throw new TypeError('baseUrl required');

  const { timeout, retries, baseUrl } = options;
  return {
    get: (path) => fetch(`${baseUrl}${path}`, { signal: AbortSignal.timeout(timeout) })
  };
}

export function paginate({
  page = 1,
  pageSize = 20,
  sort = 'createdAt',
  order = 'desc'
} = {}) {
  const offset = (page - 1) * pageSize;
  return { offset, limit: pageSize, sort, order };
}

paginate({ page: 2, pageSize: 50 });

const DEFAULTS = { tags: [] };

function create(opts = {}) {
